{"slug":"cooking-oil","unit":"tbsp","optional":false,"quantity":1}],"steps":[{"text":"青椒切絲，雞蛋打散。","step_no":1,"time_seconds":90},{"text":"蛋液加入生抽、鹽和白胡椒拌勻。","step_no":2,"time_seconds":60},{"text":"鑊中加入一半食油，中火倒入蛋液炒至半熟，先盛起。","step_no":3,"time_seconds":120},{"text":"原鑊加入餘下食油，放入青椒炒 1 至 2 分鐘。","step_no":4,"time_seconds":120},{"text":"炒蛋回鑊，快速拌勻。","step_no":5,"time_seconds":60},{"text":"蛋剛熟、青椒仍爽口即可上碟。","step_no":6,"time_seconds":60}],"previous_review":null,"time_public_note":null,"reasons":["相對編輯分類，按一份材料種類及份量，參照既有相近菜式；非即時市場價格。","以蛋、豆腐、蔬菜、少量肉碎／乾貨或罐頭為主，歸平價。"]},{"id":"b5cc0d1a-9c67-4f55-bed2-861b1d631d01","slug":"preserved-radish-omelette","name":"菜脯煎蛋","before":{"budget_level":null,"prep_time_minutes":5,"cook_time_minutes":6,"total_time_minutes":11},"after":{"budget_level":"budget","prep_time_minutes":5,"cook_time_minutes":6,"total_time_minutes":11},"ingredients":[{"slug":"spring-onion","unit":"g","optional":false,"quantity":5},{"slug":"egg","unit":"egg","optional":false,"quantity":2},{"slug":"white-pepper","unit":"tsp","optional":false,"quantity":0.25},{"slug":"cooking-oil","unit":"tbsp","optional":false,"quantity":1},{"slug":"preserved-radish","unit":"g","optional":false,"quantity":25}],"steps":[{"text":"菜脯沖洗後切碎，瀝乾水份。","step_no":1,"time_seconds":120},{"text":"雞蛋打散，加入菜脯、蔥粒和白胡椒。","step_no":2,"time_seconds":90},{"text":"平底鑊加入食油，中火加熱。","step_no":3,"time_seconds":60},{"text":"倒入蛋液，鋪平成圓形。","step_no":4,"time_seconds":60},{"text":"煎 2 至 3 分鐘至底部金黃後翻面。","step_no":5,"time_seconds":180},{"text":"另一面再煎 1 至 2 分鐘至全熟即可。","step_no":6,"time_seconds":120}],"previous_review":null,"time_public_note":null,"reasons":["相對編輯分類，按一份材料種類及份量，參照既有相近菜式；非即時市場價格。","以蛋、豆腐、蔬菜、少量肉碎／乾貨或罐頭為主，歸平價。"]},{"id":"d42a4d9c-317d-4dd1-9f7b-6169db0a5fc8","slug":"long-bean-scrambled-egg","name":"豆角炒蛋","before":{"budget_level":null,"prep_time_minutes":8,"cook_time_minutes":7,"total_time_minutes":15},"after":{"budget_level":"budget","prep_time_minutes":8,"cook_time_minutes":7,"total_time_minutes":15},"ingredients":[{"slug":"long-bean","unit":"g","optional":false,"quantity":120},{"slug":"egg","unit":"egg","optional":false,"quantity":2},{"slug":"salt","unit":"g","optional":false,"quantity":1},{"slug":"white-pepper","unit":"tsp","optional":false,"quantity":0.25},{"slug":"cooking-oil","unit":"tbsp","optional":false,"quantity":1}],"steps":[{"text":"豆角洗淨切粒，雞蛋打入碗中。","step_no":1,"time_seconds":120},{"text":"蛋液加入鹽和白胡椒打勻。","step_no":2,"time_seconds":60},{"text":"鑊中加入食油，中火先炒豆角 3 至 4 分鐘至熟。","step_no":3,"time_seconds":240},{"text":"將豆角撥開，倒入蛋液。","step_no":4,"time_seconds":30},{"text":"中小火慢慢推炒至蛋液凝固。","step_no":5,"time_seconds":90},{"text":"蛋剛熟、豆角仍爽口即可上碟。","step_no":6,"time_seconds":60}],"previous_review":null,"time_public_note":null,"reasons":["相對編輯分類，按一份材料種類及份量，參照既有相近菜式；非即時市場價格。","以蛋、豆腐、蔬菜、少量肉碎／乾貨或罐頭為主，歸平價。"]},{"id":"e678f804-19ee-4aad-a3c5-d69dcae9827d","slug":"potato-braised-chicken-wings","name":"薯仔炆雞翼","before":{"budget_level":null,"prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30},"after":{"budget_level":"normal","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30},"ingredients":[{"slug":"chicken-wings","unit":"piece","optional":false,"quantity":3},{"slug":"garlic","unit":"clove","optional":false,"quantity":1},{"slug":"oyster-sauce","unit":"tsp","optional":false,"quantity":1},{"slug":"sugar","unit":"tsp","optional":false,"quantity":0.5},{"slug":"potato","unit":"g","optional":false,"quantity":180},{"slug":"dark-soy-sauce","unit":"tsp","optional":false,"quantity":0.5},{"slug":"soy-sauce","unit":"tbsp","optional":false,"quantity":1},{"slug":"cooking-oil","unit":"tsp","optional":false,"quantity":1},{"slug":"water","unit":"ml","optional":false,"quantity":180}],"steps":[{"text":"雞中翼洗淨抹乾；薯仔去皮切件；蒜頭切蓉。","step_no":1,"time_seconds":180},{"text":"雞翼加入生抽、老抽、蠔油和糖拌勻，醃 10 分鐘。","step_no":2,"time_seconds":600},{"text":"鑊中加入 1 茶匙食油，中火煎雞翼至兩面微金黃。","step_no":3,"time_seconds":300},{"text":"加入蒜蓉和薯仔略炒 1 分鐘。","step_no":4,"time_seconds":90},{"text":"加入 180 毫升水，煮滾後轉中小火加蓋炆 15 分鐘。","step_no":5,"time_seconds":900},{"text":"開蓋收汁，薯仔軟身、雞翼熟透即可。","step_no":6,"time_seconds":180}],"previous_review":null,"time_public_note":null,"reasons":["相對編輯分類，按一份材料種類及份量，參照既有相近菜式；非即時市場價格。","以一份雞扒、豬扒、排骨、牛肉、魚柳或蜆等主材料為主，歸一般；鹹魚肉餅另含須購買的鹹魚配料。"]},{"id":"da2b2dba-09df-4bae-9b0c-0be8938be3e8","slug":"steamed-garlic-pumpkin","name":"蒜蓉蒸南瓜","before":{"budget_level":"budget","prep_time_minutes":null,"cook_time_minutes":null,"total_time_minutes":20},"after":{"budget_level":"budget","prep_time_minutes":5,"cook_time_minutes":15,"total_time_minutes":20},"ingredients":[{"slug":"garlic","unit":"clove","optional":false,"quantity":2},{"slug":"salt","unit":"g","optional":false,"quantity":1},{"slug":"soy-sauce","unit":"tsp","optional":true,"quantity":0.5},{"slug":"cooking-oil","unit":"tsp","optional":false,"quantity":1},{"slug":"pumpkin","unit":"g","optional":false,"quantity":180}],"steps":[{"text":"南瓜去皮去籽，切成約 2 厘米厚件，蒜頭切成蒜蓉。","step_no":1,"time_seconds":180},{"text":"將南瓜平鋪在碟上，避免重疊太多。","step_no":2,"time_seconds":60},{"text":"蒜蓉加入少量食油和鹽拌勻，再鋪在南瓜上。","step_no":3,"time_seconds":90},{"text":"蒸鍋水滾後放入南瓜，大火蒸 10 至 12 分鐘。","step_no":4,"time_seconds":720},{"text":"用筷子插入南瓜，如可輕易插入即熟。","step_no":5,"time_seconds":60},{"text":"取出後把碟底汁淋回南瓜表面；如選用生抽，可按材料表所列份量淋上。","step_no":6,"time_seconds":60}],"previous_review":null,"time_public_note":"備料及烹調時間按現有做法估算，未經計時試煮。按食材已解凍計；列明的醃製或冷藏等待計入備料時間。","reasons":["備料及烹調時間按現有做法估算，未經計時試煮。按食材已解凍計；列明的醃製或冷藏等待計入備料時間。"]}]$payload$::jsonb) LOOP
 SELECT id INTO rid FROM public.recipes WHERE id=(p->>'id')::uuid AND slug=p->>'slug' AND is_public FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Recipe missing: %',p->>'slug'; END IF;
 SELECT to_jsonb(r) INTO actual FROM public.recipes r WHERE id=rid;
 IF EXISTS(SELECT 1 FROM jsonb_each(p->'before')e WHERE actual->e.key IS DISTINCT FROM e.value) OR coalesce(actual->'source_data'->'budget_time_review_20261025','null'::jsonb) IS DISTINCT FROM p->'previous_review' THEN RAISE EXCEPTION 'Recipe precondition changed: %',p->>'slug'; END IF;
 SELECT count(*) INTO n FROM public.recipe_ingredients WHERE recipe_id=rid;
 IF n<>jsonb_array_length(p->'ingredients') THEN RAISE EXCEPTION 'Ingredient count changed: %',p->>'slug'; END IF;
 FOR i IN SELECT value FROM jsonb_array_elements(p->'ingredients') LOOP
  IF NOT EXISTS(SELECT 1 FROM public.recipe_ingredients ri JOIN public.ingredients g ON g.id=ri.ingredient_id JOIN public.units u ON u.id=ri.unit_id WHERE ri.recipe_id=rid AND g.slug=i->>'slug' AND ri.is_optional=(i->>'optional')::boolean AND u.code=i->>'unit' AND abs(ri.quantity-(i->>'quantity')::numeric)<=0.000000000001) THEN RAISE EXCEPTION 'Ingredient precondition changed: %',p->>'slug'; END IF;
 END LOOP;
 SELECT count(*) INTO n FROM public.recipe_steps WHERE recipe_id=rid;
 IF n<>jsonb_array_length(p->'steps') THEN RAISE EXCEPTION 'Step count changed: %',p->>'slug'; END IF;
 FOR i IN SELECT value FROM jsonb_array_elements(p->'steps') LOOP
  IF NOT EXISTS(SELECT 1 FROM public.recipe_steps s WHERE s.recipe_id=rid AND s.step_no=(i->>'step_no')::integer AND s.text=i->>'text' AND s.time_seconds IS NOT DISTINCT FROM (i->>'time_seconds')::integer) THEN RAISE EXCEPTION 'Step precondition changed: %',p->>'slug'; END IF;
 END LOOP;
 v=p->'after';
 UPDATE public.recipes SET budget_level=v->>'budget_level',prep_time_minutes=(v->>'prep_time_minutes')::integer,cook_time_minutes=(v->>'cook_time_minutes')::integer,
 source_data=coalesce(source_data,'{}'::jsonb)||jsonb_build_object('budget_time_review_20261025',jsonb_build_object('date','2026-10-25','basis','editorial_relative_budget_and_method_based_time_estimate_not_live_prices_or_kitchen_timing','before',p->'before','after',v,'reasons',p->'reasons')),updated_at=now() WHERE id=rid;
 IF p->>'time_public_note' IS NOT NULL THEN
  UPDATE public.recipes SET source_data=jsonb_set(source_data,'{consistency_review}',coalesce(source_data->'consistency_review','{}'::jsonb)||jsonb_build_object('public_notes',coalesce(source_data->'consistency_review'->'public_notes','[]'::jsonb)||jsonb_build_array(p->>'time_public_note'))) WHERE id=rid;
 END IF;
END LOOP;
END $fill$;
